let canvas = null;
let ctx = null;
let particles = [];
let raf = null;
const charCache = new Map();
function getCachedChar(char) {
    if (charCache.has(char))
        return charCache.get(char);
    const offCanvas = document.createElement("canvas");
    const offCtx = offCanvas.getContext("2d");
    const size = 128; // High resolution base for scaling
    offCanvas.width = size;
    offCanvas.height = size;
    offCtx.font = `${size * 0.8}px serif`;
    offCtx.textAlign = "center";
    offCtx.textBaseline = "middle";
    offCtx.fillText(char, size / 2, size / 2);
    charCache.set(char, offCanvas);
    return offCanvas;
}
const shapeCache = new Map();
function getCachedShape(shape, color) {
    const key = `${shape}-${color}`;
    if (shapeCache.has(key))
        return shapeCache.get(key);
    const offCanvas = document.createElement("canvas");
    const offCtx = offCanvas.getContext("2d");
    const size = 128; // Base resolution
    const r = size / 2;
    offCanvas.width = size;
    offCanvas.height = size;
    offCtx.fillStyle = color;
    offCtx.strokeStyle = color;
    offCtx.translate(r, r);
    if (shape === "smoke") {
        const grad = offCtx.createRadialGradient(0, 0, 0, 0, 0, r);
        grad.addColorStop(0, color);
        grad.addColorStop(1, "transparent");
        offCtx.fillStyle = grad;
        offCtx.beginPath();
        offCtx.arc(0, 0, r, 0, Math.PI * 2);
        offCtx.fill();
    }
    else if (shape === "snowflake") {
        offCtx.lineWidth = size * 0.1;
        offCtx.lineCap = "round";
        for (let i = 0; i < 6; i++) {
            offCtx.save();
            offCtx.rotate((i * Math.PI) / 3);
            offCtx.beginPath();
            offCtx.moveTo(0, 0);
            offCtx.lineTo(0, -r);
            offCtx.moveTo(0, -r * 0.5);
            offCtx.lineTo(-r * 0.3, -r * 0.7);
            offCtx.moveTo(0, -r * 0.5);
            offCtx.lineTo(r * 0.3, -r * 0.7);
            offCtx.stroke();
            offCtx.restore();
        }
    }
    else if (shape === "flower") {
        const petals = 6;
        for (let i = 0; i < petals; i++) {
            offCtx.save();
            offCtx.rotate((i * Math.PI * 2) / petals);
            offCtx.beginPath();
            offCtx.moveTo(0, 0);
            offCtx.bezierCurveTo(r, -r / 1.5, r, r / 1.5, 0, 0);
            offCtx.fill();
            offCtx.strokeStyle = "rgba(255, 255, 255, 0.2)";
            offCtx.lineWidth = 1;
            offCtx.stroke();
            offCtx.restore();
        }
        offCtx.beginPath();
        offCtx.arc(0, 0, r / 4, 0, Math.PI * 2);
        offCtx.fillStyle = "rgba(255, 255, 255, 0.5)";
        offCtx.fill();
    }
    shapeCache.set(key, offCanvas);
    return offCanvas;
}
function rand(a, b) {
    return a + Math.random() * (b - a);
}
function pick(arr) {
    return arr[Math.floor(Math.random() * arr.length)];
}
function init() {
    if (canvas)
        return;
    canvas = document.createElement("canvas");
    canvas.style.cssText =
        "position:fixed;top:0;left:0;width:100%;height:100%;pointer-events:none;z-index:9999";
    document.body.appendChild(canvas);
    ctx = canvas.getContext("2d");
    const resize = () => {
        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;
    };
    resize();
    window.addEventListener("resize", resize);
}
function drawShape(p) {
    if (!ctx)
        return;
    ctx.save();
    ctx.translate(p.x, p.y);
    ctx.rotate(p.rot);
    const s = p.size;
    ctx.fillStyle = p.color;
    ctx.strokeStyle = p.color;
    if (p.char) {
        const charCanvas = getCachedChar(p.char);
        // Draw the pre-rendered character canvas scaled to particle size
        ctx.drawImage(charCanvas, -s / 2, -s / 2, s, s);
    }
    else if (p.shape) {
        switch (p.shape) {
            case "circle":
                ctx.beginPath();
                ctx.arc(0, 0, s / 2, 0, Math.PI * 2);
                ctx.fill();
                break;
            case "rect":
                ctx.fillRect(-s / 2, -s / 3, s, s * 0.6);
                break;
            case "triangle":
                ctx.beginPath();
                ctx.moveTo(0, -s / 2);
                ctx.lineTo(s / 2, s / 2);
                ctx.lineTo(-s / 2, s / 2);
                ctx.closePath();
                ctx.fill();
                break;
            case "heart": {
                const r = s / 4;
                ctx.beginPath();
                ctx.moveTo(0, r);
                ctx.bezierCurveTo(r * 2, -r, r * 4, r * 2, 0, r * 4);
                ctx.bezierCurveTo(-r * 4, r * 2, -r * 2, -r, 0, r);
                ctx.fill();
                break;
            }
            case "star":
                ctx.beginPath();
                for (let i = 0; i < 10; i++) {
                    const angle = (Math.PI / 5) * i - Math.PI / 2;
                    const radius = i % 2 === 0 ? s / 2 : s / 4;
                    const x = Math.cos(angle) * radius;
                    const y = Math.sin(angle) * radius;
                    i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
                }
                ctx.closePath();
                ctx.fill();
                break;
            case "ring":
                ctx.beginPath();
                ctx.arc(0, 0, s / 2, 0, Math.PI * 2);
                ctx.lineWidth = s * 0.15;
                ctx.stroke();
                break;
            case "line":
                ctx.beginPath();
                ctx.moveTo(0, -s / 2);
                ctx.lineTo(0, s / 2);
                ctx.lineWidth = 2;
                ctx.stroke();
                break;
            case "flower":
            case "snowflake":
            case "smoke": {
                const shapeCanvas = getCachedShape(p.shape, p.color);
                ctx.drawImage(shapeCanvas, -s / 2, -s / 2, s, s);
                break;
            }
        }
    }
    ctx.restore();
}
function loop() {
    if (!ctx || !canvas)
        return;
    raf = requestAnimationFrame(loop);
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    particles = particles.filter((p) => p.life > 0);
    if (particles.length === 0) {
        if (raf !== null)
            cancelAnimationFrame(raf);
        raf = null;
        return;
    }
    for (const p of particles) {
        const alpha = p.fadeOut ? Math.min(1, (p.life / p.maxLife) * 2) : 1;
        ctx.globalAlpha = alpha;
        drawShape(p);
        p.x += p.vx;
        p.y += p.vy;
        p.vy += p.gravity;
        p.vx *= p.drag;
        p.vy *= p.drag;
        p.vx += (Math.random() - 0.5) * p.drift;
        p.rot += p.rotV;
        p.life--;
    }
    ctx.globalAlpha = 1;
}
export function burst(origin, type = "party") {
    init();
    const x = 'clientX' in origin ? origin.clientX : origin.x;
    const y = 'clientY' in origin ? origin.clientY : origin.y;
    const preset = typeof type === "string" ? PRESETS[type] : type;
    const baseAngle = preset.spreadDir ?? 0;
    const isFullCircle = preset.spread === Math.PI * 2;
    for (let i = 0; i < preset.count; i++) {
        const angle = isFullCircle
            ? Math.random() * Math.PI * 2
            : baseAngle - preset.spread / 2 + Math.random() * preset.spread;
        const speed = rand(preset.speedMin, preset.speedMax);
        const life = Math.floor(rand(preset.lifeMin, preset.lifeMax));
        const hasChars = preset.chars && preset.chars.length > 0;
        const hasShapes = preset.shapes && preset.shapes.length > 0;
        let char;
        let shape;
        if (hasChars && hasShapes) {
            if (Math.random() > 0.5)
                char = pick(preset.chars);
            else
                shape = pick(preset.shapes);
        }
        else if (hasChars) {
            char = pick(preset.chars);
        }
        else {
            shape = pick(preset.shapes);
        }
        particles.push({
            x,
            y,
            vx: Math.cos(angle) * speed + (Math.random() - 0.5) * preset.drift * 10,
            vy: Math.sin(angle) * speed + preset.riseInit,
            color: pick(preset.colors),
            shape,
            char,
            size: rand(preset.sizeMin, preset.sizeMax),
            life,
            maxLife: life,
            gravity: preset.gravity,
            drag: preset.drag,
            rot: Math.random() * Math.PI * 2,
            rotV: preset.rotates ? (Math.random() - 0.5) * 0.3 : 0,
            drift: preset.drift,
            fadeOut: preset.fadeOut,
        });
    }
    if (!raf)
        loop();
}
